def minSubArraySum(nums):
    if not nums:
        return 0

    min_sum = float('inf')
    current_sum = 0
    left = 0

    for right in range(len(nums)):
        current_sum += nums[right]

        while current_sum >= 0:
            min_sum = min(min_sum, current_sum)
            left += 1
            if left == right:
                break

    return min_sum
